#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, MOD;
    cin >> N >> MOD;
    vector<long long> DP(N, 0);
    DP[0] = 1;
    vector<long long> Cum(N + 1, 0);
    Cum[1] = 1;
    for (int i1 = 1; i1 < N; ++i1) {
        int i2 = N - i1;
        long long Value = Cum[i1];
        for (int j = 2; j <= N; ++j) {
            if (i2 * j > N) break;
            long long temp1 = Cum[N - i2 * j + 1];
            long long temp2 = 0;
            if (N - i2 * j - j + 1 > 0) {
                temp2 = Cum[N - i2 * j - j + 1];
            }
            Value += (temp1 - temp2);
            Value %= MOD;
        }
        Cum[i1 + 1] += Cum[i1] + Value;
        Cum[i1 + 1] %= MOD;
        DP[i1] = Value;
    }
    cout << DP.back() << "\n";
    return 0;
}
